async def act(page):
    """
    Plan (step-by-step):
    1. Navigate to the Sales > Orders grid at the relative path '/index.php/admin/sales_order/'.
    2. For each month from Feb (02) through Nov (11) 2022 compute start and end dates.
    3. Try to locate accessible date filter inputs using only accessibility-centric selectors (page.get_by_role).
       - First try textboxes with accessible name "From" and "To".
       - If that fails, iterate all textboxes and inspect id/name/placeholder/aria-label to find candidates containing 'from'/'to' (case-insensitive).
    4. Fill start and end dates in YYYY-MM-DD format into the discovered inputs and click the Search (or Filter) button discovered via get_by_role("button", ...).
    5. After the grid refresh, locate the orders table by scanning all tables and looking for one whose inner text contains indicators like 'Order #' or both 'Customer' and 'Grand Total'.
       Count its data rows (heuristically subtract header rows) and record the count.
    6. Print each month as MM:COUNT and return a mapping {MM:count}.

    Notes about KB helpers: none of the KB helpers provide arbitrary-month filtering on the Sales > Orders grid, so none are called. This implementation follows the instruction to prefer accessibility-role selectors (page.get_by_role).
    """
    import datetime
    import calendar

    # Helper to format month mm
    def mm_string(dt):
        return f"{dt.month:02d}"

    # Build month ranges Feb..Nov 2022
    months = []
    for m in range(2, 12):
        start = datetime.date(2022, m, 1)
        last_day = calendar.monthrange(2022, m)[1]
        end = datetime.date(2022, m, last_day)
        months.append((start, end))

    # Navigate to Sales Orders grid (relative URL)
    await page.goto('/index.php/admin/sales_order/')
    # gentle wait for a bit of network activity to settle
    try:
        await page.wait_for_load_state('networkidle', timeout=3000)
    except Exception:
        # continue even if networkidle didn't fire quickly
        pass

    results = {}

    # Utility: find a textbox locator for a label substring (searching accessible name first)
    async def find_textbox_by_name_substring(sub):
        # try direct accessible name match first
        try:
            loc = page.get_by_role('textbox', name=sub)
            if await loc.count() > 0:
                return loc.first
        except Exception:
            pass
        # fallback: scan all textboxes and inspect attributes/placeholder/aria-label
        try:
            all_count = await page.get_by_role('textbox').count()
        except Exception:
            all_count = 0
        sub_l = sub.lower()
        for i in range(all_count):
            tb = page.get_by_role('textbox').nth(i)
            try:
                info = await tb.evaluate("el => ({id: el.id||'', name: el.name||'', placeholder: el.placeholder||'', aria: el.getAttribute('aria-label')||''})")
            except Exception:
                info = {'id': '', 'name': '', 'placeholder': '', 'aria': ''}
            combined = ' '.join([info.get('id',''), info.get('name',''), info.get('placeholder',''), info.get('aria','')]).lower()
            if sub_l in combined:
                return tb
        return None

    # Utility: find a button with likely search names
    async def find_search_button():
        # prefer exact Search then Filter then Apply
        candidates = ['Search', 'Filter', 'Apply', 'Go']
        for name in candidates:
            try:
                btn = page.get_by_role('button', name=name)
                if await btn.count() > 0:
                    return btn.first
            except Exception:
                continue
        # fallback: any button with 'search' substring in accessible name
        try:
            all_btns = await page.get_by_role('button').count()
        except Exception:
            all_btns = 0
        for i in range(all_btns):
            b = page.get_by_role('button').nth(i)
            try:
                n = await b.get_attribute('aria-label')
                if not n:
                    # try inner text
                    n = (await b.inner_text() or '').strip()
                if n and 'search' in n.lower():
                    return b
            except Exception:
                continue
        return None

    # Utility: count data rows for the orders table by scanning tables
    async def count_rows_by_table_header():
        try:
            tbl_count = await page.get_by_role('table').count()
        except Exception:
            tbl_count = 0
        for i in range(tbl_count):
            tbl = page.get_by_role('table').nth(i)
            try:
                text = (await tbl.inner_text()) or ''
            except Exception:
                text = ''
            norm = text.replace('\xa0', ' ')
            if 'Order #' in norm or ('Customer' in norm and 'Grand Total' in norm) or 'Order' in norm and 'Grand Total' in norm:
                # count rows in this table
                try:
                    # count role='row' within this table
                    rows = await tbl.get_by_role('row').count()
                    # if there's at least one header row, subtract one to get data rows
                    data_rows = max(0, rows - 1)
                    return data_rows
                except Exception:
                    # fallback: try to count lines by splitting inner text by newlines and heuristic
                    try:
                        lines = [ln for ln in norm.splitlines() if ln.strip()]
                        # heuristically assume first line is header
                        if len(lines) <= 1:
                            return 0
                        return max(0, len(lines) - 1)
                    except Exception:
                        continue
        return None

    # Main loop over months
    for start, end in months:
        start_str = start.strftime('%Y-%m-%d')
        end_str = end.strftime('%Y-%m-%d')
        count = None

        # Try to set From/To textboxes
        from_tb = await find_textbox_by_name_substring('From')
        to_tb = await find_textbox_by_name_substring('To')

        # Another heuristic: some Magento filters use 'from'/'to' lowercase or phrases like 'created at from'
        if not from_tb:
            from_tb = await find_textbox_by_name_substring('created') or await find_textbox_by_name_substring('from')
        if not to_tb:
            to_tb = await find_textbox_by_name_substring('to') or await find_textbox_by_name_substring('created')

        if from_tb:
            try:
                await from_tb.fill(start_str)
            except Exception:
                try:
                    await from_tb.evaluate("(el, v) => { el.focus(); el.value = v; el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); }", start_str)
                except Exception:
                    pass
        if to_tb:
            try:
                await to_tb.fill(end_str)
            except Exception:
                try:
                    await to_tb.evaluate("(el, v) => { el.focus(); el.value = v; el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); }", end_str)
                except Exception:
                    pass

        # If we set at least one, try to click a Search button
        if from_tb or to_tb:
            btn = await find_search_button()
            if btn:
                try:
                    await btn.click()
                except Exception:
                    try:
                        # fallback JS click
                        await btn.evaluate('el => el.click()')
                    except Exception:
                        pass
                # wait for grid to refresh a bit
                try:
                    await page.wait_for_timeout(800)
                except Exception:
                    pass

        # Attempt to count rows
        try:
            count = await count_rows_by_table_header()
        except Exception:
            count = None

        # Fallback: count any rows on page and heuristically select a reasonable number
        if count is None:
            try:
                total_rows = await page.get_by_role('row').count()
                # try to subtract a couple header rows
                count = max(0, total_rows - 2)
            except Exception:
                count = 0

        # ensure int
        try:
            count = int(count or 0)
        except Exception:
            count = 0

        results[mm_string(start)] = count

    # Print results in MM:COUNT format
    for mm in sorted(results.keys()):
        print(f"{mm}:{results[mm]}")

    # Return results mapping for programmatic use
    return results

